import polars as pl

df = pl.DataFrame({
    "team": ["A", "A", "B"],
    "score": [10, 20, 15],
})

result = df.with_columns(
    pl.col("score").mean().over("team").alias("team_mean")
)
print(result)

import polars as pl

df = pl.DataFrame({
    "group": ["a", "a", "b"],
    "value": [1, 2, 3],
})
result = df.group_by("group").agg(
    total=pl.col("value").sum(),
    average=pl.col("value").mean(),
)
print(result.sort("group"))

import polars as pl

df = pl.DataFrame({
    "user": ["a", "a", "b"],
    "score": [10, 12, 8],
})

print(df.unique(subset="user", keep="first", maintain_order=True))

import polars as pl

_df = pl.DataFrame({"a": [1, 2, 3], "b": [3, 4, 5], "c": [5, 6, 7]})
result = _df.select(
    pl.fold(
        acc=pl.lit(1),
        function=lambda acc, value: acc + value,
        exprs=pl.col("*"),
    ).alias("total")
)
print(result)
